struct writerBindings
{
    // Native input slot -> the actual compact polyMesh slot.
    std::vector<label> cell, face, point, alias;
};

//- The mutable mesh the passes work on
struct cutMesh
{
    std::vector<point> points;
    std::vector<std::vector<label>> faces;
    std::vector<label> owner;       // always >= 0 for a live face
    std::vector<label> neighbour;   // -1 on a boundary face
    std::vector<label> patch;       // boundary patch id, -1 internal
    std::vector<label> zone;        // faceZone id, -1 none
    std::vector<bool> faceAlive;
    label nCells = 0;
    std::vector<bool> cellAlive;
    //- Assembled from the ORIGINAL carve (true) or added as a cut
    //  candidate (false). Only original cells anchor the fluid side.
    std::vector<bool> cellOrigAlive;
    //- Hex volume and centre of the cell each mesh cell descends from
    std::vector<scalar> cellRefVol;
    std::vector<point> cellRefCentre;
    //- Refinement level, kept for the merge heuristics
    std::vector<label> cellLevel;
    //- Rank that owns the cell; a cell of another rank in this rank's
    //  halo is cut like any other and dropped at the end. One rank (a
    //  run without -parallel) owns everything.
    std::vector<label> cellRank;
    //- Packed (i,j,k) of the octree leaf the cell descends from; with
    //  cellLevel it names the leaf identically on every rank
    std::vector<uint64_t> cellLeaf;
    //- Which piece of that leaf: a hash of the split history (A half
    //  and B half of every split). Splits are a pure function of the
    //  cell and the surfaces, so every rank that holds the piece gives
    //  it the same value; (level, leaf, piece) is the cell's global id.
    std::vector<uint64_t> cellPiece;
    //- Optional cone evidence only: input-stage parent/base labels.
    //  Empty in the ordinary path; never used by geometry or ownership.
    std::vector<label> coneEvidenceParent;
    std::vector<label> coneEvidenceBase;
    //- Points [0, nGridPoints) are octree grid corners, all further
    //  apart than the coincident-point tolerance (0: not known)
    label nGridPoints = 0;
    // Empty unless the default-OFF literal experiment builds its one
    // preoperator installed-writer oracle. Normal authorization never
    // depends on optional TRACE files.
    std::shared_ptr<writerCoupledBaseline> writerBaseline;
};

struct writerCoupledFace
{
    label nativeFace=-1, nativeOwner=-1, nativeNeighbour=-1;
    label rawPatch=-1, rawZone=-1, relativeFace=-1, compactFace=-1, compactOwner=-1;
    std::string patchName, patchType, patchRole;
    std::vector<label> nativePoints, pointAliases, ringAliases, compactPoints;
    std::vector<point> coordinates;
    vector area=vector::zero;
    point faceCentre=point::zero, cellCentre=point::zero;
    scalar volume=0;
    std::vector<std::pair<std::string,bool>> zoneRoles;
};

struct writerCoupledBaseline
{
    // Earliest immutable preoperator inputs; never updated after a union.
    std::shared_ptr<const cutMesh> checkpoint;
    std::vector<writerCoupledFace> faces;
    std::map<std::string,std::string> patchRoles;
    std::map<std::string,label> patchSizes;
    scalar copySeconds=0, constructSeconds=0, snapshotSeconds=0;
    std::size_t cutPayloadBytes=0, writerGeometryBytes=0;
};

static autoPtr<polyMesh> toPolyMesh
(
    cutMesh& m,
    const Time& runTime,
    const word& regionName,
    const wordList& patchNames,
    const wordList& patchTypes,
    const wordList& faceZoneNames,
    const wordList& patchNeighbours = wordList(),
    const wordList& patchGroups = wordList(),
    const bool baselineOnly = false,
    writerBindings* bindings = nullptr
);

// Wall-clock budget. Checked at every stage boundary — the stages are the
// only places where abandoning the run leaves nothing half-written.
scalar timeLimit = meshDict.getOrDefault<scalar>("timeLimitSeconds", 0);
args.readIfPresent("timeLimit", timeLimit);
auto budgetCheck = [&](const char* stage)
{
    if (timeLimit > 0 && timer.elapsedTime() > timeLimit)
    {
        FatalErrorInFunction
            << "dcCartMesh exceeded its " << timeLimit << " s time budget"
            << " (" << timer.elapsedTime() << " s elapsed) after '" << stage
            << "'. Aborting rather than running on: fix the mesher or raise"
            << " timeLimitSeconds in dcCartMeshDict." << nl
            << exit(FatalError);
    }
};

    meshPtr = dcCartCutCells::toPolyMesh
    (
        m, runTime, polyMesh::defaultRegion,
        patchNames, patchTypes, surfaces.faceZoneNames(),
        patchNeighbours, patchGroups
    );
    if (getenv("DCCART_CONE_LITERAL_UNIONS"))
    { budgetCheck("literal-union-final-installed-writer"); }
    const label nCellsAll = sumAll(meshPtr->nCells());
    Info<< "Cut mesh: cells " << nCellsAll << " over " << nProcs << " rank(s); this rank " << meshPtr->nCells()
        << ", points " << meshPtr->nPoints()
        << ", faces " << meshPtr->nFaces()
        << " (internal " << meshPtr->nInternalFaces() << ")"
        << "  (" << timer.timeIncrement() << " s)" << nl;
    forAll(meshPtr->faceZones(), z)
    {
        Info<< "  faceZone " << meshPtr->faceZones()[z].name() << ": "
            << meshPtr->faceZones()[z].size() << " faces" << nl;
    }
}

// OpenFOAM can report Mesh OK for a globally empty polyMesh. Never write
// that as a generated fluid mesh. Local empty partitions remain legal.
const label finalGlobalCells = returnReduce(meshPtr->nCells(), sumOp<label>());
if (finalGlobalCells <= 0)
{
    FatalErrorInFunction
        << "No fluid cells remain in the final mesh. Check locationInMesh "
        << "and the input solid/domain geometry; an empty mesh cannot be solved."
        << exit(FatalError);
}

if (!args.found("overwrite"))
{
    ++runTime;
}
meshPtr->setInstance(runTime.constant());
if (!returnReduce(meshPtr->write(), andOp<bool>()))
{
    FatalErrorInFunction
        << "Failed to write the generated mesh on every rank"
        << exit(FatalError);
}

void Foam::polyMesh::movePoints(const pointField& newPoints)
{
    DebugInFunction
        << "Moving points for time " << time().value()
        << " index " << time().timeIndex() << endl;

    if (newPoints.size() != points_.size())
    {
        FatalErrorInFunction
            << "Size of newPoints " << newPoints.size()
            << " does not correspond to current mesh points size "
            << points_.size()
            << exit(FatalError);
    }


    moving(true);

    // Pick up old points
    if (curMotionTimeIndex_ != time().timeIndex())
    {
        if (debug)
        {
            Info<< "void polyMesh::movePoints(const pointField&) : "
                << " Storing current points for time " << time().value()
                << " index " << time().timeIndex() << endl;
        }

        if (storeOldCellCentres_)
        {
            oldCellCentresPtr_.reset(nullptr);
            oldCellCentresPtr_.reset(new pointField(cellCentres()));
        }

        // Mesh motion in the new time step
        oldPointsPtr_.reset(nullptr);
        oldPointsPtr_.reset(new pointField(points_));
        curMotionTimeIndex_ = time().timeIndex();
    }

    points_ = newPoints;

    bool moveError = false;
    if (debug)
    {
        // Check mesh motion
        if (checkMeshMotion(points_, true))
        {
            moveError = true;

            InfoInFunction
                << "Moving the mesh with given points will "
                << "invalidate the mesh." << nl
                << "Mesh motion should not be executed." << endl;
        }
    }

    points_.writeOpt(IOobject::AUTO_WRITE);
    points_.instance() = time().timeName();
    points_.eventNo() = getEvent();

    if (tetBasePtIsPtr_)
    {
        tetBasePtIsPtr_->writeOpt(IOobject::AUTO_WRITE);
        tetBasePtIsPtr_->instance() = time().timeName();
        tetBasePtIsPtr_->eventNo() = getEvent();
    }

    // Currently a no-op; earlier versions set meshPhi and call
    // primitiveMesh::clearGeom
    (void)primitiveMesh::movePoints(points_, oldPoints());

    // Update the mesh geometry (via fvGeometryScheme)
    // - updateGeom is virtual -> calls fvMesh::updateGeom (or higher)
    // - fvMesh::updateGeom defers to surfaceInterpolation::updateGeom(),
    //   which defers to fvGeometryScheme::movePoints()
    // - set the mesh flux
    // - clear out/recalculate stale geometry
    updateGeom();

    // Adjust parallel shared points
    if (globalMeshDataPtr_)
    {
        globalMeshDataPtr_->movePoints(points_);
    }

    // Force recalculation of all geometric data with new points

    bounds_ = boundBox(points_);
    boundary_.movePoints(points_);

    pointZones_.movePoints(points_);
    faceZones_.movePoints(points_);
    cellZones_.movePoints(points_);

    // Reset cell tree - it gets built from mesh geometry so might have
    // wrong boxes. It is correct as long as none of the cells leaves
    // the boxes it is in which most likely is almost never the case except
    // for tiny displacements. An alternative is to check the displacements
    // to see if they are tiny - imagine a big windtunnel with a small rotating
    // object. In this case the processors without the rotating object wouldn't
    // have to clear any geometry. However your critical path still stays the
    // same so no time would be gained (unless the decomposition gets weighted).
    // Small benefit for lots of scope for problems so not done.
    cellTreePtr_.reset(nullptr);

    // Reset valid directions (could change with rotation)
    geometricD_ = Zero;
    solutionD_ = Zero;

    // Note: tet-base decomposition does not get cleared. Ideally your face
    // decomposition should not change during mesh motion ...


    meshObject::movePoints<polyMesh>(*this);
    meshObject::movePoints<pointMesh>(*this);

    const_cast<Time&>(time()).functionObjects().movePoints(*this);


    if (debug && moveError)
    {
        // Write mesh to ease debugging. Note we want to avoid calling
        // e.g. fvMesh::write since meshPhi not yet complete.
        polyMesh::write();
    }

void Foam::polyMesh::clearGeom()
{
    DebugInFunction << "Clearing geometric data" << endl;

    // Clear all geometric mesh objects
    meshObject::clear<pointMesh, GeometricMeshObject>(*this);
    meshObject::clear<polyMesh, GeometricMeshObject>(*this);

    primitiveMesh::clearGeom();

    boundary_.clearGeom();

    // Reset valid directions (could change with rotation)
    geometricD_ = Zero;
    solutionD_ = Zero;

    // Remove the cell tree
    cellTreePtr_.reset(nullptr);
}

void Foam::polyMesh::updateGeomPoints
(
    pointIOField&& newPoints,
    autoPtr<labelIOList>& newTetBasePtIsPtr
)
{
    DebugInFunction
        << "Updating geometric data with newPoints:"
        << newPoints.size() << " newTetBasePtIs:"
        << bool(newTetBasePtIsPtr) << endl;

    if (points_.size() != 0 && points_.size() != newPoints.size())
    {
        FatalErrorInFunction
            << "Point motion detected but number of points "
            << newPoints.size() << " in "
            << newPoints.objectPath() << " does not correspond to "
            << " current " << points_.size()
            << exit(FatalError);
    }

    // Clear all geometric mesh objects that are not 'movable'
    meshObject::clearUpto
    <
        pointMesh,
        TopologicalMeshObject,
        MoveableMeshObject
    >
    (
        *this
    );
    meshObject::clearUpto
    <
        polyMesh,
        TopologicalMeshObject,
        MoveableMeshObject
    >
    (
        *this
    );

    primitiveMesh::clearGeom();

    boundary_.clearGeom();

    // Reset valid directions (could change with rotation)
    geometricD_ = Zero;
    solutionD_ = Zero;

    // Remove the cell tree
    cellTreePtr_.reset(nullptr);

    // Update local data
    points_.instance() = newPoints.instance();
    points_.transfer(newPoints);

    // Optional new tet base points
    if (newTetBasePtIsPtr)
    {
        tetBasePtIsPtr_ = std::move(newTetBasePtIsPtr);
    }

    // Calculate the geometry for the patches (transformation tensors etc.)
    boundary_.calcGeometry();

    // Derived info
    bounds_ = boundBox(points_);

    // Rotation can cause direction vector to change
    geometricD_ = Zero;
    solutionD_ = Zero;

    // Update all 'movable' objects
    meshObject::movePoints<polyMesh>(*this);
    meshObject::movePoints<pointMesh>(*this);
}

